const buildHistoricalLocalityStory = (item) => {
  const presentation = historicalPresentationFrames[historicalFrameIndexes[item.slug] ?? 0](item);
  const labels = historicalEditorialLabels[item.slug] || {
    facts: `Dữ kiện chính của ${item.locality} trong năm ${item.eventYear}`,
    action: presentation.actionTitle,
    conclusion: presentation.conclusionTitle,
  };
  return {
    slug: item.slug,
    section: "Kết nối địa phương",
    title: item.title,
    description: item.description,
    lead: item.lead,
    keyword: item.keyword,
    keywords: [item.keyword, `học nghề mỏ ${item.locality}`, `việc làm TKV ${item.locality}`, "Trường Cao đẳng TKV"],
    facts: item.facts,
    factsTitle: labels.facts,
    intro: presentation.intro,
    sections: [
      {title: item.historyTitle, paragraphs: [item.history], bullets: item.bullets},
      {title: item.evidenceTitle, paragraphs: [item.evidence, item.depth[1]]},
      {title: item.policyTitle, paragraphs: [item.policy]},
      {title: item.guidanceTitle, paragraphs: [item.guidance]},
    ],
    actionTitle: labels.action,
    checklist: presentation.checklist,
    conclusionTitle: labels.conclusion,
    takeaway: item.takeaway,
    faq: presentation.faq,
    sources: [{publisher: item.publisher, title: item.sourceTitle, date: item.sourceDate, url: item.sourceUrl}],
  };
};

